            for (i = 0; i < m_coreParam.confrontRecCount; i++)
            {
                if (m_coreParam.confrontRec[i] == pokeID)
                    return;
            }

            if (i < m_coreParam.confrontRec.Length)
            {
                m_coreParam.confrontRec[i] = pokeID;
                m_coreParam.confrontRecCount++;
            }
        }
		public byte Confront_GetCount() {
            return m_coreParam.confrontRecCount;
        }
		public byte Confront_GetPokeID(byte idx) {
            if (idx >= m_coreParam.confrontRecCount)
                return PokeID.INVALID;

            return m_coreParam.confrontRec[idx];
        }
		public int GetValue(global::Dpr.Battle.Logic.BTL_POKEPARAM.ValueID vid) {
            vid = convertValueID(vid);
            switch (vid)
            {
                case ValueID.BPP_ATTACK_RANK:     return m_varyParam.attack;
                case ValueID.BPP_DEFENCE_RANK:    return m_varyParam.defence;
                case ValueID.BPP_SP_ATTACK_RANK:  return m_varyParam.sp_attack;
                case ValueID.BPP_SP_DEFENCE_RANK: return m_varyParam.sp_defence;
                case ValueID.BPP_AGILITY_RANK:    return m_varyParam.agility;
                case ValueID.BPP_HIT_RATIO:       return m_varyParam.hit;
                case ValueID.BPP_AVOID_RATIO:     return m_varyParam.avoid;
                case ValueID.BPP_ATTACK:
                    return calc.StatusRank((ushort)GetValue_Base(ValueID.BPP_ATTACK), (byte)m_varyParam.attack);
                case ValueID.BPP_DEFENCE:
                    return calc.StatusRank((ushort)GetValue_Base(ValueID.BPP_DEFENCE), (byte)m_varyParam.defence);
                case ValueID.BPP_SP_ATTACK:
                    return calc.StatusRank((ushort)GetValue_Base(ValueID.BPP_SP_ATTACK), (byte)m_varyParam.sp_attack);
                case ValueID.BPP_SP_DEFENCE:
                    return calc.StatusRank((ushort)GetValue_Base(ValueID.BPP_SP_DEFENCE), (byte)m_varyParam.sp_defence);
                case ValueID.BPP_AGILITY:
                    return calc.StatusRank((ushort)GetValue_Base(ValueID.BPP_AGILITY), (byte)m_varyParam.agility);
                case ValueID.BPP_HP:              return m_coreParam.hp;
                case ValueID.BPP_HP_BEFORE_G:     return (int)getHPBeforeG();
                case ValueID.BPP_MAX_HP:          return m_coreParam.hpMax;
                case ValueID.BPP_MAX_HP_BEFORE_G: return (ushort)m_coreParam.ppSrc.GetPower_NotG(PowerID.HP);
                case ValueID.BPP_LEVEL:           return m_coreParam.level;
                case ValueID.BPP_TOKUSEI:         return m_tokusei;
                case ValueID.BPP_TOKUSEI_EFFECTIVE:
                    if (CheckSick(WazaSick.WAZASICK_IEKI))
                        return 0;
                    if (m_fldSim != null && !m_fldSim.CheckTokuseiEffectiveOnKagakuhenkaGas((TokuseiNo)m_tokusei) && m_fldSim.IsKagakuhenkaGasEffective())
                        return 0;
                    return m_tokusei;
                case ValueID.BPP_SEX:             return m_baseParam.sex;
                case ValueID.BPP_SEIKAKU:         return m_coreParam.seikaku;
                case ValueID.BPP_PERSONAL_RAND:   return (int)m_coreParam.personalRand;
                case ValueID.BPP_EXP:             return (int)m_coreParam.exp;
                case ValueID.BPP_MONS_POW:        return m_coreParam.mons_pow;
                case ValueID.BPP_MONS_AGILITY:    return m_coreParam.mons_agility;
                default:                          return 0;
            }
        }
		public int GetValue_Base(global::Dpr.Battle.Logic.BTL_POKEPARAM.ValueID vid) {
            vid = convertValueID(vid);
            switch (vid)
            {
                case ValueID.BPP_HIT_RATIO:
                case ValueID.BPP_AVOID_RATIO:
                    return 6;
                case ValueID.BPP_ATTACK:     return m_baseParam.attack;
                case ValueID.BPP_DEFENCE:    return m_baseParam.defence;
                case ValueID.BPP_SP_ATTACK:  return m_baseParam.sp_attack;
                case ValueID.BPP_SP_DEFENCE: return m_baseParam.sp_defence;
                case ValueID.BPP_AGILITY:    return m_baseParam.agility;
                default:                     return GetValue(vid);
            }
        }
		public byte GetEffortValue(global::Pml.PokePara.PowerID powerID) {
            // No HP case in the binary (01fddbd0: `sub w8, w1, #1 ; cmp w8, #4 ; b.hi -> 0`): HP returns 0.
            switch (powerID)
            {
                case PowerID.ATK:   return m_doryokuParam.srcPow;
                case PowerID.DEF:   return m_doryokuParam.srcDef;
                case PowerID.SPATK: return m_doryokuParam.srcSpPow;
                case PowerID.SPDEF: return m_doryokuParam.srcSpDef;
                case PowerID.AGI:   return m_doryokuParam.srcAgi;
                default:            return 0;
            }
        }
		public bool IsEffortValueFull() {
            return m_doryokuParam.srcSum == PmlConstants.MAX_TOTAL_EFFORT_POWER;
        }
		public byte GetNativeTalentPower(global::Pml.PokePara.PowerID powerID) {
            switch (powerID)
            {
                case PowerID.HP:    return m_coreParam.native_talent_hp;
                case PowerID.ATK:   return m_coreParam.native_talent_atk;
                case PowerID.DEF:   return m_coreParam.native_talent_def;
                case PowerID.SPATK: return m_coreParam.native_talent_spatk;
                case PowerID.SPDEF: return m_coreParam.native_talent_spdef;
                case PowerID.AGI:   return m_coreParam.native_talent_agi;
                default:            return 0;
            }
        }
		private global::Dpr.Battle.Logic.BTL_POKEPARAM.ValueID convertValueID(global::Dpr.Battle.Logic.BTL_POKEPARAM.ValueID vid) {
            if (m_fldSim != null)
            {
                if (vid == ValueID.BPP_SP_DEFENCE)
                    return m_fldSim.CheckEffect(EffectType.EFF_WONDERROOM) ? ValueID.BPP_DEFENCE : ValueID.BPP_SP_DEFENCE;
                if (vid == ValueID.BPP_DEFENCE)
                    return m_fldSim.CheckEffect(EffectType.EFF_WONDERROOM) ? ValueID.BPP_SP_DEFENCE : ValueID.BPP_DEFENCE;
            }
            return vid;
        }
		public bool IsHPFull() {
            return GetValue(ValueID.BPP_HP) == GetValue(ValueID.BPP_MAX_HP);
        }
		public bool IsDead() {
            return GetValue(ValueID.BPP_HP) == 0;
        }
		public bool IsFightEnable() {
            if (m_coreParam.ppSrc.IsEgg(EggCheckType.BOTH_EGG))
                return false;

            return !IsDead();
        }
		public bool CheckSick(global::Pml.WazaData.WazaSick sickType) {
            return !SICKCONT.IsNull(m_coreParam.sickCont[(int)sickType]);
        }
		public bool CheckNemuri(global::Dpr.Battle.Logic.BTL_POKEPARAM.NemuriCheckMode checkMode) {
            if (checkMode == NemuriCheckMode.NEMURI_CHECK_INCLUDE_ZETTAINEMURI && GetValue(ValueID.BPP_TOKUSEI_EFFECTIVE) == (int)TokuseiNo.ZETTAINEMURI)
                return true;

            return CheckSick(WazaSick.WAZASICK_NEMURI);
        }
		public bool CheckMoudoku() {
            if (!CheckSick(WazaSick.WAZASICK_DOKU))
                return false;

            return SICKCONT.IsMoudokuCont(m_coreParam.sickCont[(int)WazaSick.WAZASICK_DOKU]);
        }
		public global::Pml.WazaNo GetWazaLockID() {
            BTL_SICKCONT cont = m_coreParam.sickCont[(int)WazaSick.WAZASICK_WAZALOCK];

            // type 1 = permanent, type 2 = turn: both params live at bits 14..29 (01fdddcc).
            if (cont.type == 1)
                return (WazaNo)cont.permanent_param;
            if (cont.type == 2)
                return (WazaNo)cont.turn_param;

            return WazaNo.NULL;
        }
		private void clearWazaSickWork(uint clearCode) {
            int startIdx = ((clearCode & (uint)SickWorkClearCode.SICKWORK_CLEAR_ONLY_WAZASICK) != 0) ? SICK_ID : 0;

            BTL_SICKCONT nemuriCont = m_coreParam.sickCont[(int)WazaSick.WAZASICK_NEMURI];
            byte nemuriCounter = m_coreParam.wazaSickCounter[(int)WazaSick.WAZASICK_NEMURI];

            for (int i = startIdx; i < m_coreParam.sickCont.Length; i++)
            {
                m_coreParam.sickCont[i].raw = 0;
                m_coreParam.sickCont[i].type = 0;
            }

            for (int i = 0; i < m_coreParam.wazaSickCounter.Length; i++)
                m_coreParam.wazaSickCounter[i] = 0;

            if ((clearCode & (uint)SickWorkClearCode.SICKWORK_CLEAR_WITHOUT_SLEEP) != 0)
            {
                m_coreParam.sickCont[(int)WazaSick.WAZASICK_NEMURI] = nemuriCont;
                m_coreParam.wazaSickCounter[(int)WazaSick.WAZASICK_NEMURI] = nemuriCounter;
            }
        }
		public global::Pml.PokePara.Sick GetPokeSick() {
            for (Sick sick = Sick.MAHI; sick < Sick.MAX; sick++)
            {
                if (CheckSick((WazaSick)sick))
                    return sick;
            }

            return Sick.NONE;
        }
		public ushort GetSickParam(global::Pml.WazaData.WazaSick sick) {
            BTL_SICKCONT cont = m_coreParam.sickCont[(int)sick];

            // 01fddf00: csel chain on type 2 / 3 / 4.
            switch (cont.type)
            {
                case 2:  return cont.turn_param;
                case 3:  return cont.poke_ID;
                case 4:  return cont.poketurn_pokeID;
                default: return 0;
            }
        }
		public global::Dpr.Battle.Logic.BTL_SICKCONT GetSickCont(global::Pml.WazaData.WazaSick sick) {
            return m_coreParam.sickCont[(int)sick];
        }
		public byte GetSickTurnCount(global::Pml.WazaData.WazaSick sick) {
            return m_coreParam.wazaSickCounter[(int)sick];
        }
		public bool IsSickLastTurn(global::Pml.WazaData.WazaSick sickType) {
            BTL_SICKCONT cont = m_coreParam.sickCont[(int)sickType];
            if (SICKCONT.IsNull(cont))
                return false;

            byte turnMax = SICKCONT.GetTurnMax(cont);
            return (turnMax - m_coreParam.wazaSickCounter[(int)sickType]) < 2;
        }
		public int CalcSickDamage(global::Pml.WazaData.WazaSick sick) {
            if (!CheckSick(sick))
                return 0;

            switch (sick)
            {
                case WazaSick.WAZASICK_YAKEDO:
                    return (int)calc.QuotMaxHP(this, 16, true);

                case WazaSick.WAZASICK_DOKU:
                    if (SICKCONT.IsMoudokuCont(m_coreParam.sickCont[(int)sick]))
                        return (int)(calc.QuotMaxHP(this, 16, true) * m_coreParam.wazaSickCounter[(int)sick]);

                    return (int)calc.QuotMaxHP(this, 8, true);

                case WazaSick.WAZASICK_AKUMU:
                    if (CheckNemuri(NemuriCheckMode.NEMURI_CHECK_INCLUDE_ZETTAINEMURI))
                        return (int)calc.QuotMaxHP(this, 4, true);

                    return 0;

                case WazaSick.WAZASICK_NOROI:
                    return (int)calc.QuotMaxHP(this, 4, true);

                default:
                    return 0;
            }
        }
		public global::Pml.WazaNo GetKodawariWazaID() {
            BTL_SICKCONT cont = m_coreParam.sickCont[(int)WazaSick.WAZASICK_KODAWARI];
            if (SICKCONT.IsNull(cont))
                return WazaNo.NULL;

            return (WazaNo)SICKCONT.GetParam(cont);
        }
		public bool IsTokuseiDisabledByKagakuHenkaGas() {
            if (m_fldSim == null)
                return false;

            if (m_fldSim.CheckTokuseiEffectiveOnKagakuhenkaGas((TokuseiNo)m_tokusei))
                return false;

            return m_fldSim.IsKagakuhenkaGasEffective();
        }
		public void ReflectToPP(bool fDefaultForm) {
            PokemonParam pp = m_coreParam.ppSrc;

            doryoku_PutToPP(m_doryokuParam, pp);
            pp.SetExp(m_coreParam.exp);
            pp.SetHp(m_coreParam.hp);

            if (m_coreParam.hp == 0)
                pp.SetSick(Sick.NONE);
            else
                pp.SetSick(GetPokeSick());

            wazaWork_ReflectToPP();

            byte formNo = (m_coreParam.fHensin || fDefaultForm) ? (byte)m_coreParam.defaultFormNo : m_formNo;
            pp.ChangeFormNo(formNo, null);
            pp.SetItem(m_coreParam.item);
        }
		private void wazaWork_UpdateNumber(global::Dpr.Battle.Logic.BTL_POKEPARAM.WAZA_SET waza, global::Pml.WazaNo nextNumber, byte ppMax, bool fPermenent) {
            if (fPermenent)
            {
                wazaCore_UpdateNumber(waza.truth, nextNumber, ppMax);
                if (waza.fLinked)
                    waza.surface.CopyFrom(waza.truth);
            }
            else
            {
                wazaCore_UpdateNumber(waza.surface, nextNumber, ppMax);
                waza.fLinked = false;
            }
        }
		private void wazaCore_UpdateNumber(global::Dpr.Battle.Logic.BTL_POKEPARAM.WAZA_CORE core, global::Pml.WazaNo nextID, byte ppMax) {
            core.number = nextID;
            core.usedFlag = false;
            core.usedFlagFix = false;
            core.usedCount = 0;
            core.killCount = 0;

            byte maxPP = (nextID != WazaNo.NULL) ? (byte)WAZADATA.GetMaxPP(nextID, 0) : (byte)0;
            if (maxPP <= ppMax || ppMax == 0)
                ppMax = maxPP;

            core.ppMax = ppMax;
            core.pp = ppMax;
        }
		private void clearHensin() {
            if (m_coreParam.fHensin)
            {
                setupBySrcData(false, true, true, true);
                wazaWork_ClearSurface();
                m_coreParam.fHensin = false;
            }
        }
		private void clearUsedWazaFlag() {
            for (int i = 0; i < m_waza.Length; i++)
                wazaSet_ClearUsedFlag(m_waza[i]);

            m_prevActWazaID = WazaNo.NULL;
            m_prevSelectWazaID = WazaNo.NULL;
            m_wazaContCounter = 0;
            m_prevWazaType = (byte)PokeType.NULL;
        }
		private void clearCounter() {
            for (int i = 0; i < m_counter.Length; i++)
                m_counter[i] = 0;
        }
