		public bool WAZA_IsPPFull(byte wazaIdx, bool fOrg) {
            WAZA_CORE core = fOrg ? m_waza[wazaIdx].truth : m_waza[wazaIdx].surface;
            if (core.number == WazaNo.NULL)
                return false;

            return core.pp == core.ppMax;
        }
		public void WAZA_DecrementPP(byte wazaIdx, byte value) {
            WAZA_CORE core = m_waza[wazaIdx].surface;
            if (core.pp >= value)
                core.pp -= value;
            else
                core.pp = 0;

            if (m_waza[wazaIdx].fLinked)
            {
                m_waza[wazaIdx].truth.pp = m_waza[wazaIdx].surface.pp;
                m_coreParam.ppSrc.SetWazaPP(wazaIdx, m_waza[wazaIdx].truth.pp);
            }
        }
		public void WAZA_DecrementPP_Org(byte wazaIdx, byte value) {
            if (m_waza[wazaIdx].fLinked)
                return;

            WAZA_CORE core = m_waza[wazaIdx].truth;
            int pp = core.pp - value;
            if (pp < 0)
                pp = 0;

            core.pp = (byte)pp;
            m_coreParam.ppSrc.SetWazaPP(wazaIdx, m_waza[wazaIdx].truth.pp);
        }
		public void WAZA_SetUsedFlag_Org(byte wazaIdx) {
            WAZA_SET waza = m_waza[wazaIdx];
            if (!waza.fLinked && !waza.truth.usedFlagFix)
            {
                waza.truth.usedFlagFix = true;
                m_usedWazaCount++;
            }
        }
		public global::Pml.WazaNo WAZA_IncrementPP(byte wazaIdx, byte value) {
            WAZA_SET waza = m_waza[wazaIdx];

            waza.surface.pp += value;
            if (waza.surface.pp > waza.surface.ppMax)
                waza.surface.pp = waza.surface.ppMax;

            if (waza.fLinked)
                waza.truth.pp = waza.surface.pp;

            return waza.surface.number;
        }
		public global::Pml.WazaNo WAZA_IncrementPP_Org(byte wazaIdx, byte value) {
            WAZA_SET waza = m_waza[wazaIdx];

            waza.truth.pp += value;
            if (waza.truth.pp > waza.truth.ppMax)
                waza.truth.pp = waza.truth.ppMax;

            if (waza.fLinked)
                waza.surface.pp = waza.truth.pp;

            return waza.truth.number;
        }
		public bool WAZA_IsLinkOut(byte wazaIdx) {
            return !m_waza[wazaIdx].fLinked;
        }
		public void WAZA_SetUsedFlag(byte wazaIdx) {
            WAZA_SET waza = m_waza[wazaIdx];

            if (!waza.surface.usedFlagFix)
            {
                waza.surface.usedFlagFix = true;
                m_usedWazaCount++;
            }

            waza.surface.usedFlag = true;

            if (waza.fLinked)
            {
                waza.truth.usedFlag = waza.surface.usedFlag;
                waza.truth.usedFlagFix = waza.surface.usedFlagFix;
            }
        }
		public void WAZA_UpdateID(byte wazaIdx, global::Pml.WazaNo waza, byte ppMax, bool fPermenent) {
            wazaWork_UpdateNumber(m_waza[wazaIdx], waza, ppMax, fPermenent);

            if (fPermenent)
            {
                PokemonParam pp = m_coreParam.ppSrc;
                pp.SetWaza(wazaIdx, m_waza[wazaIdx].truth.number);
                pp.SetWazaPPUpCount(wazaIdx, m_waza[wazaIdx].truth.ppCnt);
                pp.SetWazaPP(wazaIdx, m_waza[wazaIdx].truth.pp);
            }
        }
		public bool WAZA_IsUsable(global::Pml.WazaNo waza) {
            for (int i = 0; i < m_waza.Length; i++)
            {
                if (m_waza[i].surface.number == waza)
                    return true;
            }
            return false;
        }
		public byte WAZA_SearchIdx(global::Pml.WazaNo waza) {
            if (waza == WazaNo.NULL)
                return BattleDefConst.PTL_WAZA_MAX;

            for (byte i = 0; i < BattleDefConst.PTL_WAZA_MAX; i++)
            {
                if (m_waza[i].surface.number == waza)
                    return i;
            }
            return BattleDefConst.PTL_WAZA_MAX;
        }
		private void splitTypeCore(out byte type1, out byte type2) {
            bool isHaneyasume = CheckSick(WazaSick.WAZASICK_HANEYASUME);

            type1 = (isHaneyasume && m_baseParam.type1 == (byte)PokeType.HIKOU) ? (byte)PokeType.NULL : m_baseParam.type1;
            type2 = (isHaneyasume && m_baseParam.type2 == (byte)PokeType.HIKOU) ? (byte)PokeType.NULL : m_baseParam.type2;

            bool isMoetukiru = CONTFLAG_Get(ContFlag.CONTFLG_MOETUKIRU);

            if (type1 == (byte)PokeType.NULL)
            {
                if (type2 == (byte)PokeType.NULL)
                {
                    if (!isMoetukiru)
                    {
                        type2 = (byte)PokeType.NORMAL;
                        type1 = (byte)PokeType.NORMAL;
                    }
                }
                else
                {
                    type1 = type2;
                }
            }
            else if (type2 == (byte)PokeType.NULL)
            {
                type2 = type1;
            }
        }
