		public byte GetCriticalRank() {
            byte rank = m_criticalRank;

            if (CONTFLAG_Get(ContFlag.CONTFLG_KIAIDAME))
                rank += 2;

            if (CheckSick(WazaSick.WAZASICK_TOGISUMASU))
                rank += 3;

            if (rank > DefineConstants.BTL_CALC_CRITICAL_MAX)
                rank = DefineConstants.BTL_CALC_CRITICAL_MAX;

            return rank;
        }
		public byte GetCriticalRankPure() {
            return m_criticalRank;
        }
		public bool AddCriticalRank(int value) {
            if (value > 0)
            {
                if (m_criticalRank >= DefineConstants.BTL_CALC_CRITICAL_MAX)
                    return false;

                byte rank = (byte)(m_criticalRank + value);
                if (rank > DefineConstants.BTL_CALC_CRITICAL_MAX)
                    rank = DefineConstants.BTL_CALC_CRITICAL_MAX;

                m_criticalRank = rank;
                return true;
            }

            if (m_criticalRank == 0)
                return false;

            if (-value < m_criticalRank)
                m_criticalRank = (byte)(m_criticalRank + value);
            else
                m_criticalRank = 0;

            return true;
        }
		public void SetCriticalRank(byte rank) {
            if (rank <= DefineConstants.BTL_CALC_CRITICAL_MAX)
                m_criticalRank = rank;
        }
