		public void SetWazaSick(global::Pml.WazaData.WazaSick sick, in global::Dpr.Battle.Logic.BTL_SICKCONT contParam) {
            if (calc.IsBasicSickID(sick))
                CurePokeSick();

            m_coreParam.sickCont[(int)sick] = contParam;
            m_coreParam.wazaSickCounter[(int)sick] = 0;
        }
		public bool WazaSick_TurnCheck(global::Pml.WazaData.WazaSick sick, out global::Dpr.Battle.Logic.BTL_SICKCONT pOldContDest, out bool fCured) {
            pOldContDest = SICKCONT.MakeNull();
            fCured = false;

            if (sick == WazaSick.WAZASICK_NEMURI || sick == WazaSick.WAZASICK_KONRAN)
                return false;

            if (!CheckSick(sick))
                return false;

            byte turnMax = SICKCONT.GetTurnMax(m_coreParam.sickCont[(int)sick]);

            BTL_SICKCONT oldCont = m_coreParam.sickCont[(int)sick];
            pOldContDest = oldCont;
            fCured = false;

            if (sick == WazaSick.WAZASICK_KODAWARI)
            {
                WazaNo kodawariWaza = (WazaNo)SICKCONT.GetParam(oldCont);
                if (!WAZA_IsUsable(kodawariWaza))
                {
                    m_coreParam.sickCont[(int)sick] = SICKCONT.MakeNull();
                    m_coreParam.wazaSickCounter[(int)sick] = 0;
                    fCured = true;
                }
            }

            if (turnMax != 0)
            {
                m_coreParam.wazaSickCounter[(int)sick]++;
                if (m_coreParam.wazaSickCounter[(int)sick] >= turnMax)
                {
                    m_coreParam.sickCont[(int)sick] = SICKCONT.MakeNull();
                    m_coreParam.wazaSickCounter[(int)sick] = 0;
                    fCured = true;
                }
            }
            else
            {
                BTL_SICKCONT cont = m_coreParam.sickCont[(int)sick];

                // type 1 = permanent: count up to permanent_count_max (01fe1310).
                if (cont.type == 1 && cont.permanent_count_max != 0)
                {
                    if (m_coreParam.wazaSickCounter[(int)sick] < cont.permanent_count_max)
                        m_coreParam.wazaSickCounter[(int)sick]++;
                }
            }

            return true;
        }
		public bool CheckNemuriWakeUp() {
            if (!CheckSick(WazaSick.WAZASICK_NEMURI))
                return false;

            byte turnMax = SICKCONT.GetTurnMax(m_coreParam.sickCont[(int)WazaSick.WAZASICK_NEMURI]);
            if (turnMax == 0)
                return false;

            byte inc = IsMatchTokusei(TokuseiNo.HAYAOKI) ? (byte)2 : (byte)1;
            m_coreParam.wazaSickCounter[(int)WazaSick.WAZASICK_NEMURI] += inc;

            return m_coreParam.wazaSickCounter[(int)WazaSick.WAZASICK_NEMURI] >= turnMax;
        }
		public bool CheckKonranWakeUp() {
            if (!CheckSick(WazaSick.WAZASICK_KONRAN))
                return false;

            byte turnMax = SICKCONT.GetTurnMax(m_coreParam.sickCont[(int)WazaSick.WAZASICK_KONRAN]);
            if (turnMax == 0)
                return false;

            m_coreParam.wazaSickCounter[(int)WazaSick.WAZASICK_KONRAN]++;

            return m_coreParam.wazaSickCounter[(int)WazaSick.WAZASICK_KONRAN] >= turnMax;
        }
		public void CurePokeSick() {
            for (Sick sick = Sick.MAHI; sick < Sick.MAX; sick++)
            {
                m_coreParam.sickCont[(int)sick] = SICKCONT.MakeNull();
                m_coreParam.wazaSickCounter[(int)sick] = 0;
                cureDependSick((WazaSick)sick);
            }
        }
		private void cureDependSick(global::Pml.WazaData.WazaSick sickID) {
            if (sickID == WazaSick.WAZASICK_NEMURI)
            {
                m_coreParam.sickCont[(int)WazaSick.WAZASICK_AKUMU] = SICKCONT.MakeNull();
                m_coreParam.wazaSickCounter[(int)WazaSick.WAZASICK_AKUMU] = 0;
            }
        }
		public void CureWazaSick(global::Pml.WazaData.WazaSick sick) {
            if (calc.IsBasicSickID(sick))
            {
                CurePokeSick();
                return;
            }

            m_coreParam.sickCont[(int)sick] = SICKCONT.MakeNull();
            m_coreParam.wazaSickCounter[(int)sick] = 0;
        }
		public void CureWazaSickDependPoke(byte depend_pokeID) {
            if (depend_pokeID == PokeID.INVALID)
                return;

            for (int i = 0; i < (int)WazaSick.WAZASICK_MAX; i++)
            {
                if (SICKCONT.IsNull(m_coreParam.sickCont[i]))
                    continue;

                if (SICKCONT.GetPokeID(m_coreParam.sickCont[i]) == depend_pokeID)
                {
                    // The counter of the cured sick itself is left untouched (01fe1730).
                    m_coreParam.sickCont[i] = SICKCONT.MakeNull();
                    cureDependSick((WazaSick)i);
                }
            }
        }
