		public void Clear_ForDead() {
            flgbuf_clear(m_turnFlag);
            flgbuf_clear(m_contFlag);

            clearHensin();
            wazaWork_ClearSurface();
            clearUsedWazaFlag();
            clearCounter();
            CombiWaza_ClearParam();
            FakeDisable();
            resetSpActPriority();
            MIGAWARI_Delete();
            clearWazaSickWork((uint)SickWorkClearCode.SICKWORK_CLEAR_ALL);
            effrank_Reset(m_varyParam);

            m_formNo = (byte)m_coreParam.defaultFormNo;
            m_tokusei = m_coreParam.defaultTokusei;
            m_coreParam.ppSrc.ChangeFormNo(m_formNo, null);

            correctMaxHP();
            updateWeight();

            if (m_coreParam.isRaidBoss)
                CurePokeSick();
        }
		public void Clear_ForOut() {
            flgbuf_clear(m_turnFlag);

            clearHensin();
            wazaWork_ClearSurface();
            clearUsedWazaFlag();
            clearCounter();
            CombiWaza_ClearParam();
            FakeDisable();
            resetSpActPriority();

            if (!CONTFLAG_Get(ContFlag.CONTFLG_BATONTOUCH))
            {
                MIGAWARI_Delete();
                clearWazaSickWork((uint)(SickWorkClearCode.SICKWORK_CLEAR_WITHOUT_SLEEP | SickWorkClearCode.SICKWORK_CLEAR_ONLY_WAZASICK));
                effrank_Reset(m_varyParam);
                flgbuf_clear(m_contFlag);
            }

            if (m_coreParam.fDontResetFormByByOut)
            {
                m_formNo = (byte)m_coreParam.ppSrc.GetFormNo();
                m_tokusei = (ushort)m_coreParam.ppSrc.GetTokuseiNo();
            }
            else
            {
                m_formNo = (byte)m_coreParam.defaultFormNo;
                m_tokusei = m_coreParam.defaultTokusei;
                m_coreParam.ppSrc.ChangeFormNo(m_formNo, null);
            }
        }
