        }
		public void CopyBatonTouchParams(global::Dpr.Battle.Logic.BTL_POKEPARAM user) {
            m_varyParam.CopyFrom(user.m_varyParam);
            m_migawariHP = user.m_migawariHP;

            for (int i = 0; i < (int)WazaSick.WAZASICK_MAX; i++)
            {
                if (user.CheckSick((WazaSick)i) && BTL_SICK.CheckBatonTouchInherit((WazaSick)i, this))
                {
                    m_coreParam.sickCont[i] = user.m_coreParam.sickCont[i];
                    m_coreParam.wazaSickCounter[i] = user.m_coreParam.wazaSickCounter[i];
                }
            }

            if (user.CONTFLAG_Get(ContFlag.CONTFLG_POWERTRICK))
            {
                CONTFLAG_Set(ContFlag.CONTFLG_POWERTRICK);

                ushort attack = m_baseParam.attack;
                m_baseParam.attack = (ushort)GetValue_Base(ValueID.BPP_DEFENCE);
                SetBaseStatus(ValueID.BPP_DEFENCE, attack);
            }

            if (user.CONTFLAG_Get(ContFlag.CONTFLG_KIAIDAME))
                CONTFLAG_Set(ContFlag.CONTFLG_KIAIDAME);

            user.MIGAWARI_Delete();
            user.clearWazaSickWork((uint)SickWorkClearCode.SICKWORK_CLEAR_ONLY_WAZASICK);
            user.effrank_Reset(user.m_varyParam);
            user.flgbuf_clear(user.m_contFlag);
        }
		public bool ChangePokeType(global::Dpr.Battle.Logic.PokeTypePair type, global::Dpr.Battle.Logic.BTL_POKEPARAM.ExTypeCause exTypeCause) {
            byte prevType1 = m_baseParam.type1;
            byte prevType2 = m_baseParam.type2;
            byte prevTypeEx = m_baseParam.type_ex;

            m_baseParam.type1 = PokeTypePair.GetType1(type);
            m_baseParam.type2 = PokeTypePair.GetType2(type);
            m_baseParam.type_ex = PokeTypePair.GetTypeEx(type);
            m_baseParam.type_ex_cause = exTypeCause;

            if (((prevType1 == m_baseParam.type1 && prevType2 == m_baseParam.type2) ||
                 (prevType2 == m_baseParam.type1 && prevType1 == m_baseParam.type2)) &&
                prevTypeEx == m_baseParam.type_ex)
            {
                return false;
            }

            return true;
        }
