		private void correctMaxHP() {
            bool isGMode = IsGMode();
            int prevHP = GetValue(ValueID.BPP_HP);
            int prevMaxHP = GetValue(ValueID.BPP_MAX_HP);

            ushort maxHP = getBasePower(PowerID.HP, isGMode);
            m_coreParam.hpMax = maxHP;

            if (maxHP > prevMaxHP)
                HpPlus((ushort)(maxHP - prevMaxHP));

            if (maxHP < prevMaxHP && maxHP < prevHP)
                HpMinus((ushort)(prevHP - maxHP));
        }
