		public void WAZADMGREC_Add(global::Dpr.Battle.Logic.BTL_POKEPARAM.WAZADMG_REC rec) {
            byte turnPtr = m_dmgrecTurnPtr;
            int idx = m_dmgrecCount[turnPtr];

            if (idx == WAZADMG_REC_MAX)
            {
                // Shifts the record REFERENCES down by one (array stores, not CopyFrom — 01fe2860).
                for (int i = 0; i < WAZADMG_REC_MAX - 1; i++)
                    m_wazaDamageRec[turnPtr][i] = m_wazaDamageRec[turnPtr][i + 1];

                idx = WAZADMG_REC_MAX - 1;
            }

            // Stores the caller's object itself (reference), as the binary does.
            m_wazaDamageRec[turnPtr][idx] = rec;

            if (m_dmgrecCount[turnPtr] < WAZADMG_REC_MAX)
                m_dmgrecCount[turnPtr]++;
        }
		public byte WAZADMGREC_GetCount(byte turn_ridx) {
            if (turn_ridx >= WAZADMG_REC_TURN_MAX)
                return 0;

            int turnIdx = m_dmgrecTurnPtr - turn_ridx;
            if (turnIdx < 0)
                turnIdx += WAZADMG_REC_TURN_MAX;

            return m_dmgrecCount[turnIdx];
        }
		public bool WAZADMGREC_Get(byte turn_ridx, byte rec_ridx, global::Dpr.Battle.Logic.BTL_POKEPARAM.WAZADMG_REC dst) {
            if (turn_ridx >= WAZADMG_REC_TURN_MAX)
                return false;

            int turnIdx = m_dmgrecTurnPtr - turn_ridx;
            if (turnIdx < 0)
                turnIdx += WAZADMG_REC_TURN_MAX;

            byte count = m_dmgrecCount[turnIdx];
            if (rec_ridx >= count)
                return false;

            dst.CopyFrom(m_wazaDamageRec[turnIdx][(byte)(count - 1 - rec_ridx)]);
            return true;
        }
