		private void doryoku_InitParam(global::Dpr.Battle.Logic.BTL_POKEPARAM.DORYOKU_PARAM work, global::Pml.PokePara.PokemonParam pp) {
            work.srcSum = 0;
            for (int i = 0; i < calc.PokePowerIDTable.Length; i++)
            {
                ref byte value = ref doryoku_ParamIDtoValueAdrs(work, calc.PokePowerIDTable[i]);
                value = (byte)pp.GetEffortPower(calc.PokePowerIDTable[i]);
                work.srcSum += value;
            }

            work.srcG = pp.GetEffortG();
            work.bPokerus = pp.HavePokerusUntilNow();
            work.bModified = false;
        }
		private void doryoku_AddPower(global::Dpr.Battle.Logic.BTL_POKEPARAM.DORYOKU_PARAM work, global::Pml.PokePara.PowerID powID, byte value) {
            if (value == 0 || work.srcSum >= PmlConstants.MAX_TOTAL_EFFORT_POWER)
                return;

            // Byte arithmetic kept: with srcSum 254 the clamp yields (byte)256 = 0 and nothing is added (01fe3b98).
            if (work.srcSum + value > PmlConstants.MAX_TOTAL_EFFORT_POWER)
                value = (byte)(PmlConstants.MAX_TOTAL_EFFORT_POWER - work.srcSum);

            if (value == 0)
                return;

            ref byte power = ref doryoku_ParamIDtoValueAdrs(work, powID);
            if (power + value > PmlConstants.MAX_EFFORT_POWER)
                value = (byte)(PmlConstants.MAX_EFFORT_POWER - power);

            power += value;
            work.srcSum += value;
            work.bModified = true;
        }
		private void doryoku_PutToPP(global::Dpr.Battle.Logic.BTL_POKEPARAM.DORYOKU_PARAM work, global::Pml.PokePara.PokemonParam pp) {
            if (!work.bModified)
                return;

            bool fastMode = pp.StartFastMode();

            for (int i = 0; i < calc.PokePowerIDTable.Length; i++)
            {
                ref byte value = ref doryoku_ParamIDtoValueAdrs(work, calc.PokePowerIDTable[i]);
                pp.ChangeEffortPower(calc.PokePowerIDTable[i], value);
            }

            pp.ChangeEffortG(work.srcG);
            work.bModified = false;
            pp.EndFastMode(fastMode);
        }
		private ref byte doryoku_ParamIDtoValueAdrs(global::Dpr.Battle.Logic.BTL_POKEPARAM.DORYOKU_PARAM work, global::Pml.PokePara.PowerID powID) {
            switch (powID)
            {
                case PowerID.HP:    return ref work.srcHp;
                case PowerID.ATK:   return ref work.srcPow;
                case PowerID.DEF:   return ref work.srcDef;
                case PowerID.SPATK: return ref work.srcSpPow;
                case PowerID.SPDEF: return ref work.srcSpDef;
                case PowerID.AGI:   return ref work.srcAgi;
                default:            return ref s_DmyByte;
            }
        }
